mapper.select:
SELECT hour_of_day, avg_occupancy, avg_demand, avg_supply, gap, imbalance FROM v_hourly_supply_demand
AND hour_of_day >= #{hourFrom}
AND hour_of_day <= #{hourTo}
ORDER BY hour_of_day

SELECT zone_id, longitude, latitude, hour_of_day, demand_share, supply_share, imbalance, rank_no FROM v_imbalance_top
AND zone_id = #{zoneId}
AND hour_of_day >= #{hourFrom}
AND hour_of_day <= #{hourTo}
ORDER BY imbalance DESC LIMIT #{limit}

SELECT zone_id,
       forecast_date,
       hour_of_day,
       predict_volume,
       actual_volume,
       mape
FROM v_forecast_series


        AND zone_id = #{zoneId}


        AND forecast_date >= #{startDate}


        AND forecast_date <= #{endDate}


ORDER BY forecast_date, hour_of_day
LIMIT #{limit}

SELECT zone_id, volume, volume_11kw, deviation FROM v_volume_deviation
AND zone_id = #{zoneId}
ORDER BY deviation DESC

SELECT zone_id, poi_total, poi_density, pile_density, avg_occupancy FROM v_poi_correlation
AND zone_id = #{zoneId}
ORDER BY poi_density DESC
